function R(a,b){return Math.floor(Math.random()*(b-a+1))+a;}
function P(a){return a[R(0,a.length-1)];}
function PN(a,n){const s=[...a];const r=[];for(let i=0;i<n&&s.length;i++){const j=R(0,s.length-1);r.push(s.splice(j,1)[0]);}return r;}
function RK(v){return Math.round(v/500)*500;}
function VP(b){return RK(b*(0.7+Math.random()*0.6));}
function WH(){const d={};['monday','tuesday','wednesday','thursday','friday'].forEach(k=>{d[k]={start:'09:00',end:'18:00',isActive:true,isToday:false};});d.saturday={start:'10:00',end:'16:00',isActive:true,isToday:false};d.sunday={start:'10:00',end:'16:00',isActive:false,isToday:false};return d;}
function SA(){const d=P(D);return[d,P(D.filter(x=>x[0]!==d[0]))[0]||d];}

